import type { DocumentNode } from "graphql";

/**
 * Register your app by augmenting this interface, through `@nxlab/olio`
 * (which re-exports it):
 *
 * ```ts
 * declare module "@nxlab/olio" {
 *   interface Olio {
 *     application: Application; // generated by @nxlab/codegen
 *     ctx: GQLCtx;
 *     sub_ctx: SubGQLCtx;
 *     mappers: { User: UserRow }; // optional: what resolvers use for a type
 *   }
 * }
 * ```
 */
// oxlint-disable-next-line typescript/no-empty-interface -- augmented by apps
export interface Olio {}

/** What the app registered as `ctx`; @nxlab/http requires a `context` hook building it. */
export type Context = Olio extends { ctx: infer C } ? C : unknown;

export type TypeSource = string | DocumentNode;

/** A glob string, or a `file:` URL such as `new URL("*.gql", import.meta.url)`. */
export type Pattern = string | URL;

export type ResolverMap = Record<string, object>;

/** Middleware as a module carries it; olio's `MiddlewareMap` is the typed view. */
export type StoredMiddleware = Partial<
  Record<string, Partial<Record<string, readonly unknown[]>>>
>;

declare const loaded: unique symbol;

/**
 * What `loadResolvers` returns. Files are typed where they're written (with
 * the builders), so a loaded map isn't checked again; the brand keeps inline
 * maps from slipping through as one.
 */
// `never` values fit every typed entry, so a loaded map passes the same type
// as an inline one: a union of the two would hide which inline field is wrong.
export type LoadedResolvers = { readonly [type: string]: never } & {
  readonly [loaded]: true;
};

declare const loadedEnums: unique symbol;

/**
 * What `loadEnums` returns: it satisfies a required `enums` unchecked, as a
 * loaded resolver map does `resolvers`; each file is typed by its builder.
 */
export type LoadedEnums = { readonly [type: string]: never } & {
  readonly [loadedEnums]: true;
};

/** What `olio()` takes: built by `createModule` / `module.<id>`. */
export interface OlioModule {
  readonly id: string;
  readonly typeDefs: readonly DocumentNode[];
  readonly resolvers: readonly ResolverMap[];
  readonly enums: ResolverMap;
  readonly middleware: StoredMiddleware;
  readonly features: readonly OlioFeature[];
}

/** Isolated: resolves only what its own SDL declares, like a module. */
export interface OlioFeature {
  readonly module: string;
  readonly id: string;
  readonly typeDefs: readonly DocumentNode[];
  readonly resolvers: readonly ResolverMap[];
  readonly enums: ResolverMap;
  readonly middleware: StoredMiddleware;
}
